import React from 'react';
import {AbsoluteFill, useS, en, T, Entrar} from './kit';

const CHIP = {x: 372, y: 860};

const Tarjeta: React.FC<{s: number}> = ({s}) => (
  <g>
    <defs>
      <linearGradient id="plas" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#1f6fa8" /><stop offset="1" stopColor="#0d2f55" /></linearGradient>
      <linearGradient id="oroC" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#ffe9a0" /><stop offset="0.5" stopColor="#d9a93a" /><stop offset="1" stopColor="#8a6216" /></linearGradient>
      <radialGradient id="mesaC" cx="0.5" cy="0.45"><stop offset="0" stopColor="#6d4526" /><stop offset="1" stopColor="#21120a" /></radialGradient>
    </defs>
    <rect width={1080} height={1920} fill="url(#mesaC)" />
    {[...Array(14).keys()].map((i) => <path key={i} d={`M0 ${i * 145 + 30}Q540 ${i * 145 + 70 - (i % 3) * 30} 1080 ${i * 145 + 20}`} stroke="#160b05" strokeWidth={2 + (i % 3)} fill="none" opacity={0.5} />)}
    <g transform={`rotate(${-4 + Math.sin(s * 0.8) * 1.2} 540 900)`}>
      <rect x={110} y={662} width={880} height={560} rx={46} fill="#000" opacity={0.42} />
      <rect x={90} y={630} width={880} height={560} rx={46} fill="url(#plas)" />
      <rect x={90} y={1010} width={880} height={12} fill="#fff" opacity={0.08} />
      <path d={`M${90 + ((s * 170) % 1300) - 300} 630l300 0l-260 560l-300 0Z`} fill="#fff" opacity={0.07} />
      <rect x={270} y={785} width={190} height={146} rx={22} fill="url(#oroC)" />
      <path d="M270 858H460M365 785V931M270 822H325M405 822H460M270 894H325M405 894H460" stroke="#7a5412" strokeWidth={5} fill="none" />
      <text x={170} y={1090} fontFamily="Poppins, sans-serif" fontWeight={700} fontSize={58} letterSpacing={7} fill="#e8eef5">5412 •••• •••• 7781</text>
    </g>
  </g>
);

const Dentro: React.FC<{s: number; t0: number}> = ({s, t0}) => {
  const c = en('compra'), no = en('copiarla');
  const ronda = Math.floor(Math.max(0, s - c) / 0.55);
  const cod = ['A7F3', 'Q91K', 'Z4M8', 'K2X6', 'T8B1', 'P5R9'][ronda % 6];
  const pistas = [...Array(16).keys()].map((i) => {
    const y = 130 + i * 112;
    const m = 300 + ((i * 137) % 480);
    return `M${i % 2 ? -20 : 1100} ${y}H${m}L${i % 3 ? 540 : m + 60} ${i < 8 ? 690 : 1130}`;
  });
  const z = 1 + (s - t0) * 0.025;
  return (
    <g transform={`translate(540 900) scale(${z}) translate(-540 -900)`}>
      <rect x={-200} y={-200} width={1480} height={2320} fill="#07101f" />
      {[...Array(30).keys()].map((i) => <rect key={i} x={(i * 271) % 1080} y={(i * 419) % 1920} width={70 + (i * 17) % 160} height={36 + (i * 11) % 60} rx={4} fill="#10233f" />)}
      {pistas.map((d, i) => <path key={i} d={d} stroke="#b98a27" strokeWidth={9} fill="none" opacity={0.55} />)}
      {pistas.map((d, i) => <path key={'l' + i} d={d} stroke="#ffe08a" strokeWidth={11} strokeLinecap="round" fill="none" pathLength={100} strokeDasharray="5 95" strokeDashoffset={-((s * (38 + i * 3) + i * 13) % 100)} />)}
      <rect x={250} y={680} width={580} height={460} rx={26} fill="#172c4e" stroke="#ffd166" strokeWidth={8} />
      {[...Array(9).keys()].map((i) => <rect key={i} x={290 + (i % 3) * 170} y={720 + Math.floor(i / 3) * 130} width={150} height={110} rx={8} fill={Math.floor(s * 5 + i * 2) % 5 === 0 ? '#2d77c9' : '#21406f'} />)}
      {s >= c && <g><rect x={320} y={830} width={440} height={170} rx={20} fill="#fffdf6" /><text x={540} y={950} textAnchor="middle" fontFamily="Poppins, sans-serif" fontWeight={900} fontSize={118} fill={s >= no ? '#d9363e' : '#17324f'}>{cod}</text></g>}
    </g>
  );
};

export const Escena: React.FC = () => {
  const {s} = useS();
  const t = en('Dentro');
  return (
    <AbsoluteFill style={{background: '#000'}}>
      <svg width={1080} height={1920} style={{position: 'absolute'}}>
        <Entrar t={t - 0.2} x={CHIP.x} y={CHIP.y} dur={1.2} zoom={18} fuera={<Tarjeta s={s} />} dentro={<Dentro s={s} t0={t} />} />
      </svg>
    </AbsoluteFill>
  );
};
export const CORTES: number[] = [];
export const SUBS = {arriba: 210, size: 64, acento: '#ffd166'};
export const SFX = [{t: T(0), s: 'pop_01'}, {t: en('Dentro') - 0.2, s: 'whoosh_01'}, {t: en('compra'), s: 'tick_02'}, {t: en('copiarla'), s: 'ding_01'}];
